def maximumPoints(n, k, stayScore, travelScore):
    # prev[j]: best score so far if the tourist is in city j after day 0
    prev = []
    for j in range(n):
        best = stayScore[0][j]                        # start at j and stay
        for i in range(n):
            if i != j:
                best = max(best, travelScore[i][j])   # start at i and move to j
        prev.append(best)

    for day in range(1, k):
        curr = []
        for city in range(n):
            best = prev[city] + stayScore[day][city]  # stay in city
            for p in range(n):
                if p != city:                          # move from p to city
                    best = max(best, prev[p] + travelScore[p][city])
            curr.append(best)
        prev = curr
    return max(prev)
